const projects = window.PORTFOLIO_PROJECTS;
const external = 'target="_blank" rel="noopener noreferrer"';
function visual(p) {
  if (p.id === 'athenaeum') return `<div class="visual-top"><strong>athenæum<span style="color:var(--accent)">.</span></strong><span>LIBRARY PLATFORM</span></div><div class="mock-panel"><div class="mock-title">One connected library workflow</div><div class="mock-row"><span>Browse & reserve</span><span>01</span></div><div class="mock-row"><span>Borrow & renew</span><span>02</span></div><div class="mock-row"><span>Return & reconcile</span><span>03</span></div></div><span class="visual-foot">PROJECT CONCEPT / NOT A LIVE DASHBOARD</span>`;
  if (p.id === 'resume') return `<div class="visual-top"><strong>Resume / reimagined</strong><span>GEN AI</span></div><div class="mock-panel"><div class="mock-title">A clearer path to your next role</div><div class="mock-row"><span>Resume + job description</span><span>→</span></div><div class="mock-row"><span>Context-aware analysis</span><span>→</span></div><div class="mock-row"><span>Targeted preparation</span><span>↗</span></div></div><span class="visual-foot">PROJECT WORKFLOW</span>`;
  if (p.id === 'neuro') return `<div class="visual-top"><strong>NeuroBehavior AI</strong></div><div class="signal" aria-hidden="true">${[22,40,31,56,38,60,46,28].map(h=>`<i style="height:${h}px"></i>`).join('')}</div><div class="mock-title">8 features · 5 stress classes</div><span class="visual-foot">RESEARCH / DECORATIVE SIGNAL VISUAL</span>`;
  return `<img class="project-photo" src="assets/technology.jpg" alt="" loading="lazy" width="1600" height="1201"><div class="photo-content visual-top"><strong>${p.id==='transport'?'IN MOTION':'CONNECTED CARE'}</strong><span>IoT</span></div><div class="photo-content photo-label">${p.id==='transport'?'Devices.<br>Data. Direction.':'Sense.<br>Connect. Understand.'}</div><span class="photo-content visual-foot" style="color:#c5c8dd">EARLY UNDERGRADUATE PROJECT</span>`;
}
function links(p) { return `${p.live?`<a href="${p.live}" ${external}>Live project ↗</a>`:''}${p.github?`<a href="${p.github}" ${external}>GitHub ↗</a>`:''}`; }
document.querySelector('#projects').innerHTML=projects.map(p=>`<article class="project ${p.id}"><div class="project-visual">${visual(p)}</div><p class="project-meta">${p.number} / ${p.category}</p><h3>${p.title}</h3><p class="project-description">${p.description}</p><div class="tags">${p.tags.map(t=>`<span>${t}</span>`).join('')}</div><div class="project-actions">${links(p)}<button data-project="${p.id}" aria-haspopup="dialog">${p.id==='neuro'?'Research notes':'Project details'} +</button></div></article>`).join('');
const themeButton=document.querySelector('#theme');
function setTheme(theme){document.documentElement.dataset.theme=theme;themeButton.textContent=theme==='dark'?'☼':'☾';themeButton.setAttribute('aria-label',`Switch to ${theme==='dark'?'light':'dark'} theme`);document.querySelector('meta[name="theme-color"]').content=theme==='dark'?'#11121a':'#f7f7fc';}
try{setTheme(localStorage.getItem('portfolio-theme')==='light'?'light':'dark')}catch{setTheme('dark')}
themeButton.addEventListener('click',()=>{const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';setTheme(theme);try{localStorage.setItem('portfolio-theme',theme)}catch{}});
const menu=document.querySelector('#menu'),nav=document.querySelector('#navigation');
function closeMenu(){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation');menu.textContent='☰'}
menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');menu.textContent=open?'✕':'☰'});
nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});
const dialog=document.querySelector('#project-dialog');let lastTrigger;
document.querySelectorAll('[data-project]').forEach(button=>button.addEventListener('click',()=>{const p=projects.find(p=>p.id===button.dataset.project);lastTrigger=button;document.querySelector('#dialog-content').innerHTML=`<h2 id="dialog-title">${p.title}</h2><p>${p.subtitle}</p><div class="tags">${p.tags.map(t=>`<span>${t}</span>`).join('')}</div><ul>${p.points.map(t=>`<li>${t}</li>`).join('')}</ul><div class="project-actions">${links(p)}</div>`;dialog.setAttribute('aria-labelledby','dialog-title');dialog.showModal();document.body.classList.add('modal-open')}));
document.querySelector('#close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{const r=dialog.getBoundingClientRect();if(e.target===dialog&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))dialog.close()});dialog.addEventListener('close',()=>{document.body.classList.remove('modal-open');lastTrigger?.focus()});
document.querySelector('#copy-email').addEventListener('click',async()=>{const status=document.querySelector('#copy-status');try{await navigator.clipboard.writeText('abhinavprasad286@gmail.com');status.textContent='Email address copied.'}catch{status.textContent='Please copy: abhinavprasad286@gmail.com'}});
document.querySelector('#year').textContent=new Date().getFullYear();
if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){nav.querySelectorAll('a').forEach(a=>{const active=a.getAttribute('href')==='#'+entry.target.id;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})}})},{rootMargin:'-15% 0px -55% 0px'});document.querySelectorAll('main section[id]').forEach(section=>observer.observe(section))}
